create table if not exists public.kc_system_check_alert_settings (id text, push_enabled boolean, email_enabled boolean, push_min_severity text, email_min_severity text, check_interval_minutes integer, recovery_push_enabled boolean, recovery_email_enabled boolean, last_full_status text, last_evaluated_at timestamp with time zone, last_alert_status text, last_alert_at timestamp with time zone, updated_at timestamp with time zone, primary key (id));
