create table if not exists public.kc_termin_buchungen (id uuid, slot_id uuid, einladung_id uuid, personen integer, besuchsart text, status text, erstellt_am timestamp with time zone, entschieden_am timestamp with time zone, bestaetigung_gesendet_am timestamp with time zone, erinnerung_gesendet_am timestamp with time zone, besuch_id text, primary key (id));
