create table if not exists public.kc_verwaltung_logistics_staff (assignment_id uuid, plan_id uuid, org_id text, step_code text, planned_headcount integer, planned_date date, role text, names text, status text, notes text, created_at timestamp with time zone, updated_at timestamp with time zone, primary key (assignment_id));
