create table if not exists public.kicc_program_heartbeats (program_id text, instance_id text, version text, build text, status text, measured_at timestamp with time zone, received_at timestamp with time zone, latency_ms integer, traffic_rx bigint, traffic_tx bigint, queue_depth integer, error_count integer, source_id text, trust text, primary key (program_id, instance_id));
